CREATE TABLE IF NOT EXISTS fb_companies (
 id CHAR(32) PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL,account_id BIGINT UNSIGNED NOT NULL UNIQUE,
 status VARCHAR(20) NOT NULL,created BIGINT NOT NULL,next_tax BIGINT NOT NULL,debt BIGINT NOT NULL DEFAULT 0,overdue BIGINT NULL,liquidate_until BIGINT NULL,
 withdrawal_limit BIGINT NOT NULL DEFAULT 10000,daily_limit INT NOT NULL DEFAULT 10,dividend_mode VARCHAR(20) NOT NULL DEFAULT 'disabled',dividend_amount BIGINT NOT NULL DEFAULT 0,reserve_minor BIGINT NOT NULL DEFAULT 0,next_dividend BIGINT NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_shares (company_id CHAR(32) NOT NULL,character_id VARCHAR(64) NOT NULL,units INT NOT NULL,PRIMARY KEY(company_id,character_id),FOREIGN KEY(company_id) REFERENCES fb_companies(id),CHECK(units BETWEEN 1 AND 10000)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_ranks (id CHAR(32) PRIMARY KEY,company_id CHAR(32) NOT NULL,name VARCHAR(60) NOT NULL,level_no INT NOT NULL,wage BIGINT NOT NULL,rights LONGTEXT NOT NULL,FOREIGN KEY(company_id) REFERENCES fb_companies(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_employees (character_id VARCHAR(64) PRIMARY KEY,company_id CHAR(32) NOT NULL,rank_id CHAR(32) NOT NULL,seconds_online INT NOT NULL DEFAULT 0,pay_seq BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(company_id) REFERENCES fb_companies(id),FOREIGN KEY(rank_id) REFERENCES fb_ranks(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_invites (id CHAR(32) PRIMARY KEY,company_id CHAR(32) NOT NULL,target_id VARCHAR(64) NOT NULL,rank_id CHAR(32) NOT NULL,wage BIGINT NOT NULL,expires BIGINT NOT NULL,INDEX(target_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_licenses (owner_type VARCHAR(12) NOT NULL,owner_id VARCHAR(64) NOT NULL,category VARCHAR(32) NOT NULL,active BOOLEAN NOT NULL,next_tax BIGINT NOT NULL,debt BIGINT NOT NULL DEFAULT 0,overdue BIGINT NULL,PRIMARY KEY(owner_type,owner_id,category)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_proposals (id CHAR(32) PRIMARY KEY,company_id CHAR(32) NOT NULL,kind VARCHAR(32) NOT NULL,payload LONGTEXT NOT NULL,voters LONGTEXT NOT NULL,approvals LONGTEXT NOT NULL,status VARCHAR(20) NOT NULL,created BIGINT NOT NULL,expires BIGINT NOT NULL,INDEX(company_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id CHAR(32) NOT NULL,actor VARCHAR(64) NOT NULL,action VARCHAR(48) NOT NULL,detail LONGTEXT NOT NULL,created BIGINT NOT NULL,INDEX(company_id,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_jobs (id CHAR(32) PRIMARY KEY,kind VARCHAR(32) NOT NULL,payload LONGTEXT NOT NULL,created BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_locations (company_id CHAR(32) NOT NULL,property_id CHAR(32) NOT NULL,grantor VARCHAR(64) NOT NULL,rights LONGTEXT NOT NULL,PRIMARY KEY(company_id,property_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_storage (id CHAR(32) PRIMARY KEY,company_id CHAR(32) NOT NULL,property_id CHAR(32) NOT NULL,name VARCHAR(60) NOT NULL,x DOUBLE NOT NULL,y DOUBLE NOT NULL,z DOUBLE NOT NULL,INDEX(company_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_receipts (id CHAR(32) PRIMARY KEY,owner_type VARCHAR(12) NOT NULL,owner_id VARCHAR(64) NOT NULL,reference_id VARCHAR(96) NOT NULL,detail LONGTEXT NOT NULL,hidden BOOLEAN NOT NULL DEFAULT FALSE,created BIGINT NOT NULL,UNIQUE(owner_type,owner_id,reference_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fb_withdrawals (id CHAR(32) PRIMARY KEY,company_id CHAR(32) NOT NULL,day_no BIGINT NOT NULL,amount BIGINT NOT NULL,INDEX(company_id,day_no)) ENGINE=InnoDB;
